def tw(a,b): a=dict(a); a['twin']=b; return a
def reason(q,pic,ids): return {"t":"reason","q":q,"pic":pic,"opts":[{"id":ids[0],"ok":True},{"id":ids[1]},{"id":ids[2]}]}
MAT=lambda: {"prompt":"mat.01","show":[],"icon":True,"after":"mat.02","facts":[]}
BAG=lambda a,b,la,lb: {"items":[{"icon":a,"label":la},{"icon":b,"label":lb}],"ask":"bag.ask"}
def c9p(**o): return {"kind":"pfpic","c9":o}
XF={'refV':lambda p:(-p[0],p[1]),'refH':lambda p:(p[0],-p[1]),'rot90':lambda p:(-p[1],p[0]),'rot180':lambda p:(-p[0],-p[1]),'rot270':lambda p:(p[1],-p[0])}
def ap(s,p): return (p[0]+s[1],p[1]+s[2]) if isinstance(s,list) else XF[s](p)
def run(seq,p):
    for s in seq: p=ap(s,p)
    return p
PTS=set(); KEYS={}; AMB=[]
def uniq(t,k):
    k=t+'|'+k; KEYS[k]=KEYS.get(k,0)+1
def pick_cands(p,xf):
    x,y=p; img=XF[xf](p); alt={'refV':[(x,-y),(-x,-y)],'refH':[(-x,y),(-x,-y)],'rot90':[(y,-x),(y,x),(-x,-y)],'rot270':[(-y,x),(y,x),(-x,-y)],'rot180':[(-x,y),(x,-y),(-y,x)]}[xf]
    out=[]
    for c in [img,*alt,(-y,-x),(x+1,y)]:
        if c not in out and c!=tuple(p): out.append(c)
    return out[:3]
def pick(p,xf):
    p=tuple(p); assert XF[xf](p)!=p, (p,xf); C=pick_cands(p,xf); assert len(C)==3,(p,xf,C); PTS.update(C); PTS.add(p); uniq('pick','%s|%s'%(p,xf))
    return {"t":"c9Pick","p":list(p),"xf":xf,"q":"gen.c9.q.pick."+xf}
def draw(pts,xf,on=False):
    img=[XF[xf](tuple(p)) for p in pts]; assert all(max(abs(a),abs(b))<=8 for a,b in img)
    assert on==(img==[tuple(p) for p in pts]), (pts,xf)   # النقطة على المرآة مقصودةٌ وحدها (المراجع A لبوابة M4-U9، 15)
    for k in list(XF)+['id']:   # الحكم بالمجموعة لا بالترتيب: لا تحويل آخر (ولا الإبقاء) يعطي مجموعة الرؤوس نفسها (المراجع B لبوابة M4-U9، 6)
        if k!=xf and not (on and k=='id') and sorted((XF[k](tuple(p)) if k!='id' else tuple(p)) for p in pts)==sorted(img): AMB.append((pts,xf,k))
    uniq('draw','%s|%s'%(pts,xf))
    d={"t":"c9Draw","pts":[list(p) for p in pts],"xf":xf,"q":"gen.c9.q.draw.%s%s"%('pt.' if len(pts)==1 else '',xf)}
    if on: d["r"]="gen.c9.reveal.onMirror"
    return d
def which(p,xf): uniq('which','%s|%s'%(p,xf)); return {"t":"c9Which","p":list(p),"xf":xf,"q":"gen.c9.q.which"}
def name(pts,xf):
    img=[XF[xf](tuple(p)) for p in pts]
    for k in XF:   # الشكل غير متماثل: لا تحويل آخر يعطي الصورة نفسها
        if k!=xf: assert sorted(XF[k](tuple(p)) for p in pts)!=sorted(img), (pts,xf,k)
    uniq('name','%s|%s'%(pts,xf)); return {"t":"c9NameIt","pts":[list(p) for p in pts],"xf":xf,"q":"gen.c9.q.name"}
def rot(th,ask='ang',cw=False,r=5,off=0):
    assert th%10==0 and 10<=th<=170; uniq('rot','%s|%s|%s|%s'%(th,cw,r,ask))
    # الشعاع الأدنى عند b من الأفقي (يتنوّع بين البنود)، والدوران فوقه حتى 172 درجة: الشكل والمنقلة داخل الإطار (المراجع B لبوابة M4-U9، 2 و11)
    b=max(4,min(172-th, 6+((th//10)*7+(9 if cw else 0)+(abs(off)//10)*5+len(ask)*3)%25))
    assert 4<=b and b+th<=172 and r<=6, (th,b,r)
    d={"t":"c9Rot","th":th,"ask":ask,"q":"gen.c9.q.rot."+ask,"b":b}
    if cw: d["cw"]=True
    if r!=5: d["r"]=r
    return d
def comp(p,seq,ask='img'):
    p=tuple(p); mid=ap(seq[0],p); img=run(seq,p); back=run([seq[1],seq[0]],p)
    if ask=='img':
        C=[]
        for c in [img,mid,ap(seq[1],p),back,(img[0],-img[1]),(-img[0],img[1])]:
            if c not in C and c!=p: C.append(c)
        PTS.update(C[:3]); assert len(C)>=3
    if ask=='one': assert any(XF[k](p)==img for k in ('rot90','rot180','refV','refH')), (p,seq)
    PTS.add(p); uniq('comp','%s|%s|%s'%(p,seq,ask))
    return {"t":"c9Comp","p":list(p),"seq":seq,"ask":ask,"q":"gen.c9.q.comp"}
# جولات الألعاب الحركية (D288 (2)): بنودٌ حركية يشغّلها المشهد motion بنمط التمرين
def trs(p,goal,q):
    p=tuple(p); g=tuple(goal); assert g in (XF['refV'](p),XF['refH'](p),XF['rot180'](p)) and g!=p, (p,g); uniq('trs','%s|%s'%(p,g)); PTS.update([p,g])
    return {"t":"c9Trs","p":list(p),"goal":list(g),"q":q}
def whl(p,k,q,match=False):
    p=tuple(p); assert 1<=k<=3; uniq('whl','%s|%s'%(p,k)); d={"t":"c9Whl","p":list(p),"k":k,"q":q}
    if match: d["match"]=True
    return d
def door(kind,th,cw,b,qc,qa,b0=None):   # جولةٌ بخطوتين: المركز ثم المنقلة والقراءة؛ الشعاعان مضاعفا 10، والصفر الأول ليس على أحدهما
    assert th%30==0 and b%10==0 and 0<=b and b+th<=180, (th,b); lo=b; ok=[lo,lo+th-180]; b0=lo-30 if b0 is None else b0; assert b0 not in ok and b0%10==0 and -40<=b0<=40 and -40<=lo<=40, (b0,ok)   # المنقلة تدور بين −40 و40 فتبقى في الإطار
    c={"t":"c9DrC","kind":kind,"th":th,"b":b,"q":qc}; a={"t":"c9DrA","kind":kind,"th":th,"b":b,"b0":b0,"q":qa}
    if cw: c["cw"]=True; a["cw"]=True
    return [c,a]

