# ---------------- د3: الدوران بالمنقلة والفرجار (C422) وتركيب التحويلات ----------------
L3={
 "bag.ask":"هَلْ {مَعَكَ|مَعَكِ} مِنْقَلَةٌ وَفِرْجَارٌ؟ أَمْ نَعْمَلُ عَلَى الشَّاشَةِ؟",
 "hk.01":["chaos","الدَّوَرَانُ لَا يَكُونُ إِلَّا رُبْعَ دَوْرَةٍ أَوْ نِصْفَهَا، فَلَا عَمَلَ لِلْمِنْقَلَةِ هُنَا!"],
 "hk.02":"بَابُ المَدِينَةِ يَدُورُ أَرْبَعِينَ دَرَجَةً فَقَطْ. فَلْنَتَعَلَّمِ الدَّوَرَانَ بِأَيِّ زَاوِيَةٍ.",
 "pt.01":"المَرْكَزُ مِيمْ، وَالنُّقْطَةُ أَلِفْ. نَرْسُمُ نِصْفَ المُسْتَقِيمِ مِنْ مِيمْ إِلَى أَلِفْ.",
 "pt.02":"نَضَعُ مَرْكَزَ المِنْقَلَةِ عَلَى مِيمْ، وَصِفْرَهَا عَلَى مِيمْ أَلِفْ، وَنَعُدُّ خَمْسِينَ دَرَجَةً عَكْسَ عَقَارِبِ السَّاعَةِ.",
 "pt.03":"وَنَرْسُمُ نِصْفَ مُسْتَقِيمٍ ثَانِيًا مِنْ مِيمْ.",
 "pt.04":"نَفْتَحُ الفِرْجَارَ بِطُولِ مِيمْ أَلِفْ، وَنَرْسُمُ قَوْسًا يَقْطَعُ نِصْفَ المُسْتَقِيمِ الثَّانِي فِي صُورَةِ أَلِفْ: بُعْدُهَا عَنْ مِيمْ هُوَ بُعْدُ أَلِفْ.",
 "pt.05":"القَاعِدَةُ: الدَّوَرَانُ يَحْتَاجُ مَرْكَزًا وَزَاوِيَةً وَاتِّجَاهًا، وَكُلُّ نُقْطَةٍ تَبْقَى عَلَى بُعْدِهَا مِنَ المَرْكَزِ، فَالأَطْوَالُ وَالزَّوَايَا لَا تَتَغَيَّرُ.",
 "tm.01":"النُّقْطَةُ ثَلَاثَةٌ، وَاحِدٌ. نَعْكِسُهَا عَلَى المِحْوَرِ الرَّأْسِيِّ، فَصُورَتُهَا: سَالِبُ ثَلَاثَةٍ، وَاحِدٌ.",
 "tm.02":"ثُمَّ نَعْكِسُ الصُّورَةَ عَلَى المِحْوَرِ الأُفُقِيِّ، فَصُورَتُهَا الجَدِيدَةُ: سَالِبُ ثَلَاثَةٍ، سَالِبُ وَاحِدٍ.",
 "tm.03":"وَهَذِهِ صُورَتُهَا بِنِصْفِ دَوْرَةٍ حَوْلَ الأَصْلِ! انْعِكَاسَانِ عَلَى المِحْوَرَيْنِ يُسَاوِيَانِ نِصْفَ دَوْرَةٍ، بِأَيِّ تَرْتِيبٍ.",
 "tm.04":"نُجَرِّبُ نُقَطًا أُخْرَى فَتَتَّفِقُ النَّتِيجَتَانِ كُلَّ مَرَّةٍ، وَنَتْرُكُ بُرْهَانَ ذَلِكَ إِلَى مَا بَعْدُ.",
 "tm.q5":"نَعْكِسُ النُّقْطَةَ وَاحِدٌ، اثْنَانِ عَلَى المِحْوَرِ الرَّأْسِيِّ ثُمَّ نَسْحَبُهَا ثَلَاثَةً إِلَى اليَمِينِ، أَوْ نَسْحَبُهَا أَوَّلًا ثُمَّ نَعْكِسُ: هَلْ تَتَّفِقُ الصُّورَتَانِ؟",
 "tm.05":"أَمَّا انْعِكَاسٌ عَلَى المِحْوَرِ الرَّأْسِيِّ ثُمَّ انْسِحَابٌ ثَلَاثَةً إِلَى اليَمِينِ، فَتَبْدِيلُ تَرْتِيبِهِمَا يُغَيِّرُ النَّتِيجَةَ: الصُّورَتَانِ فِي مَكَانَيْنِ مُخْتَلِفَيْنِ.",
 "mat.01":"{اُرْسُمْ|اُرْسُمِي} مَرْكَزًا وَنُقْطَةً، {وَدَوِّرْهَا|وَدَوِّرِيهَا} بِزَاوِيَةٍ {تَخْتَارُهَا|تَخْتَارِينَهَا} بِالمِنْقَلَةِ، {وَانْقُلِ|وَانْقُلِي} البُعْدَ بِالفِرْجَارِ. ثُمَّ {اِلْمِسْ|اِلْمِسِي} «تَمَّ».",
 "mat.02":"وَالآنَ عَلَى الشَّاشَةِ.",
 "dr.00":"لُعْبَةُ «البَابِ الدَّوَّارِ»: نَجِدُ مَرْكَزَ الدَّوَرَانِ، ثُمَّ نَضَعُ عَلَيْهِ المِنْقَلَةَ وَنَقِيسُ الزَّاوِيَةَ.",
 "dr.01":"نَرَى البَابَ مُغْلَقًا بِالدَّاكِنِ، وَمَفْتُوحًا بِالفَاتِحِ. {اِلْمِسْ|اِلْمِسِي} مَرْكَزَ الدَّوَرَانِ: النُّقْطَةَ الَّتِي يَدُورُ البَابُ حَوْلَهَا.",
 "dr.02":"{ضَعِ|ضَعِي} المِنْقَلَةَ: {أَدِرْهَا|أَدِيرِيهَا} بِالزِّرَّيْنِ حَتَّى يَقَعَ صِفْرُهَا عَلَى أَحَدِ وَضْعَيِ البَابِ، ثُمَّ «تَمَّ».",
 "dr.03":"وَهَذِهِ رَايَةٌ زَرْقَاءُ وَصُورَتُهَا البُرْتُقَالِيَّةُ بِدَوَرَانٍ. أَيُّ النِّقَاطِ الثَّلَاثِ مَرْكَزُ الدَّوَرَانِ؟ {اِلْمِسْهَا|اِلْمِسِيهَا} فَيَدُورُ الشَّفَّافُ حَوْلَهَا.",
 "dr.04":"{أَدِرِ|أَدِيرِي} المِنْقَلَةَ حَتَّى يَقَعَ صِفْرُهَا عَلَى أَحَدِ الخَطَّيْنِ مِنَ المَرْكَزِ، ثُمَّ «تَمَّ».",
 "dr.end":"{أَحْسَنْتَ|أَحْسَنْتِ}: المَرْكَزُ ثَابِتٌ لَا يَتَحَرَّكُ، وَالمِنْقَلَةُ عَلَيْهِ تَقِيسُ الزَّاوِيَةَ.",
 "mr.00":"لُعْبَةُ «مِرْآتَانِ»: هَلْ يَصْدُقُ مَا اكْتَشَفْنَاهُ عَلَى نُقْطَةٍ جَدِيدَةٍ؟",
 "mr.01":"{اِعْكِسِ|اِعْكِسِي} النُّقْطَةَ عَلَى المِحْوَرِ الرَّأْسِيِّ: {اِلْمِسْ|اِلْمِسِي} مَوْضِعَ صُورَتِهَا.",
 "mr.02":"ثُمَّ {اِعْكِسِ|اِعْكِسِي} الصُّورَةَ عَلَى المِحْوَرِ الأُفُقِيِّ.",
 "mr.03":"وَالآنَ {أَدِرِ|أَدِيرِي} النُّقْطَةَ الأُولَى حَوْلَ الأَصْلِ حَتَّى تَنْطَبِقَ عَلَى الصُّورَةِ الأَخِيرَةِ، ثُمَّ «تَمَّ».",
 "mr.end":"كَمَا اكْتَشَفْنَا: المِرْآتَانِ عَلَى المِحْوَرَيْنِ تُسَاوِيَانِ نِصْفَ دَوْرَةٍ.",
 "pr.intro":"نَتَدَرَّبُ.",
 "pr.r1":"قَالَتْ فَوْضَى: الانْعِكَاسَانِ المُتَتَالِيَانِ عَلَى المِحْوَرَيْنِ يُغَيِّرَانِ الشَّكْلَ. مَا خَطَؤُهَا؟",
 "pr.r1a":"الشَّكْلُ يَبْقَى كَمَا هُوَ، وَالانْعِكَاسَانِ مَعًا يُسَاوِيَانِ نِصْفَ دَوْرَةٍ.",
 "pr.r1b":"لَا خَطَأَ: الشَّكْلُ يَنْقَلِبُ مَرَّتَيْنِ، فَيَصِيرُ مَقْلُوبًا كَمَا فِي المِرْآةِ.",
 "pr.r1c":"الخَطَأُ أَنَّ الانْعِكَاسَيْنِ يُعِيدَانِ النُّقْطَةَ إِلَى مَكَانِهَا.",
 "ch.find":"قَالَتْ فَوْضَى: زَاوِيَةُ الدَّوَرَانِ مِئَةٌ وَعَشْرُ دَرَجَاتٍ، قَرَأْتُهَا مِنَ المِنْقَلَةِ. كَمْ هِيَ حَقًّا؟",
 "ch.after":["chaos","آه! نَعُدُّ مِنَ الصِّفْرِ الَّذِي عَلَى مِيمْ أَلِفْ."],
 "ch.right":"نَقْرَأُ مِنَ الصِّفْرِ الَّذِي عَلَى مِيمْ أَلِفْ.",
 "ch.wrong":["chaos","أَيُّ تَدْرِيجٍ يَكْفِي."],
 "ms.1":"لِمَاذَا تَبْقَى صُورَةُ النُّقْطَةِ عَلَى البُعْدِ نَفْسِهِ مِنَ المَرْكَزِ؟",
 "ms.1a":"الفِرْجَارُ يَنْقُلُ البُعْدَ نَفْسَهُ، فَالدَّوَرَانُ يَحْفَظُ الأَطْوَالَ.",
 "ms.1b":"المِنْقَلَةُ تَحْفَظُ الزَّاوِيَةَ، وَالزَّاوِيَةُ وَحْدَهَا تُحَدِّدُ مَوْضِعَ الصُّورَةِ.",
 "ms.1c":"الصُّورَةُ تَقْتَرِبُ مِنَ المَرْكَزِ كُلَّمَا كَبُرَتِ الزَّاوِيَةُ.",
 "ms.x1":"بَابٌ يَدُورُ حَوْلَ مُفَصَّلَتِهِ. لِمَاذَا يَرْسُمُ طَرَفُهُ عَلَى الأَرْضِ قَوْسًا مِنْ دَائِرَةٍ؟",
 "ms.x1a":"لِأَنَّ طَرَفَهُ يَبْقَى عَلَى البُعْدِ نَفْسِهِ مِنَ المُفَصَّلَةِ، وَهِيَ مَرْكَزُ الدَّوَرَانِ.",
 "ms.x1b":"لِأَنَّ البَابَ يَقْتَرِبُ مِنَ المُفَصَّلَةِ كُلَّمَا دَارَ، فَيَنْحَنِي طَرِيقُ طَرَفِهِ.",
 "ms.x1c":"لِأَنَّ زَاوِيَةَ الدَّوَرَانِ تِسْعُونَ دَرَجَةً، وَكُلُّ دَوَرَانٍ بِتِسْعِينَ دَرَجَةً يَرْسُمُ قَوْسًا.",
 "ms.recall":"نَتَذَكَّرُ: نَضَعُ مَرْكَزَ المِنْقَلَةِ عَلَى المَرْكَزِ وَصِفْرَهَا عَلَى الخَطِّ الأَوَّلِ، ثُمَّ نَفْتَحُ الفِرْجَارَ مِنَ المَرْكَزِ إِلَى النُّقْطَةِ.",
 "ms.ok":"{أَتْقَنْتَ|أَتْقَنْتِ} الدَّوَرَانَ بِالمِنْقَلَةِ وَتَرْكِيبَ التَّحْوِيلَاتِ!",
 "wrap.01":"مَرْكَزٌ وَزَاوِيَةٌ وَاتِّجَاهٌ، وَمِرْآتَانِ تَصْنَعَانِ دَوْرَةً!",
 "wrap.home":["chaos","مُهِمَّةُ البَيْتِ: {اِفْتَحْ|اِفْتَحِي} مَعَ {أَهْلِكَ|أَهْلِكِ} بَابَ الغُرْفَةِ، {وَقِسْ|وَقِيسِي} زَاوِيَةَ دَوَرَانِهِ بِالمِنْقَلَةِ عِنْدَ المُفَصَّلَةِ."],
}
